styles:
/**
 * 算法技能 settings-section styles.
 *
 * Every colour is a theme alias token — no literal colour, no invented token.
 * That rule has teeth here: this repo's `theme-tokens` gate fails the build on
 * a token that no official package defines, because the failure mode is silent
 * (a misspelt `var()` falls back to a literal forever and simply stops tracking
 * the theme, which looks fine in light mode and wrong in dark). The radius
 * family in particular does NOT exist on this platform — the panel uses literal
 * radii in px, the same choice the role matrix makes.
 *
 * The four levels are visually ranked by indent plus weight rather than by four
 * different accent colours, so the hierarchy survives both themes and a future
 * re-brand of the single accent.
 */

._root_f9beb7 {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 2px 0 8px;
  min-width: 0;
}

/* ── 页头 ─────────────────────────────────────────────── */
._head_f9beb7 {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

._headRow_f9beb7 {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

._title_f9beb7 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  line-height: 22px;
  color: var(--dsw-alias-label-primary);
}

._subtitle_f9beb7 {
  margin: 0;
  font-size: 12px;
  line-height: 18px;
  color: var(--dsw-alias-label-secondary);
}

._path_f9beb7 {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  line-height: 16px;
  color: var(--dsw-alias-label-tertiary);
  word-break: break-all;
}

/* ── 统计条 ───────────────────────────────────────────── */
._stats_f9beb7 {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

._stat_f9beb7 {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 7px 12px;
  border: 1px solid var(--dsw-alias-border-l1);
  border-radius: 10px;
  background: var(--dsw-alias-bg-layer-1);
  min-width: 0;
}

._statValue_f9beb7 {
  font-size: 15px;
  font-weight: 600;
  line-height: 20px;
  color: var(--dsw-alias-label-primary);
  font-variant-numeric: tabular-nums;
}

._statLabel_f9beb7 {
  font-size: 11px;
  line-height: 15px;
  color: var(--dsw-alias-label-tertiary);
}

._statWarn_f9beb7 ._statValue_f9beb7 {
  color: var(--dsw-alias-state-warn-primary);
}

/* ── 工具行 ───────────────────────────────────────────── */
._toolbar_f9beb7 {
  display: flex;
  align-items: center;
  gap: 8px;
}

._search_f9beb7 {
  box-sizing: border-box;
  flex: 1;
  min-width: 0;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--dsw-alias-border-l1);
  border-radius: 8px;
  background: var(--dsw-alias-bg-layer-1);
  color: var(--dsw-alias-label-primary);
  font-size: 13px;
  line-height: 20px;
  outline: none;
}

._search_f9beb7:focus {
  border-color: var(--dsw-alias-brand-primary);
}

._search_f9beb7::placeholder {
  color: var(--dsw-alias-label-secondary);
}

._tool_f9beb7 {
  flex: none;
  border: 1px solid var(--dsw-alias-border-l1);
  background: transparent;
  color: var(--dsw-alias-label-secondary);
  border-radius: 8px;
  padding: 5px 10px;
  font: inherit;
  font-size: 12px;
  line-height: 18px;
  cursor: pointer;
}

._tool_f9beb7:hover {
  background: var(--dsw-alias-interactive-bg-hover);
  color: var(--dsw-alias-label-primary);
}

._hitCount_f9beb7 {
  flex: none;
  font-size: 12px;
  line-height: 18px;
  color: var(--dsw-alias-label-tertiary);
  font-variant-numeric: tabular-nums;
}

/* ── 诊断条 ───────────────────────────────────────────── */
._issues_f9beb7 {
  border: 1px solid var(--dsw-alias-border-l1);
  border-radius: 10px;
  background: var(--dsw-alias-bg-layer-1);
  overflow: hidden;
}

._issuesHead_f9beb7 {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  border: none;
  background: transparent;
  padding: 8px 12px;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: var(--dsw-alias-state-warn-primary);
  font-size: 12px;
  line-height: 18px;
}

._issuesBody_f9beb7 {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 0 12px 10px 26px;
  max-height: 180px;
  overflow-y: auto;
}

._issueLine_f9beb7 {
  font-size: 11px;
  line-height: 16px;
  color: var(--dsw-alias-label-secondary);
}

/* ── 面 ───────────────────────────────────────────────── */
._plane_f9beb7 {
  border: 1px solid var(--dsw-alias-border-l1);
  border-radius: 12px;
  background: var(--dsw-alias-bg-layer-1);
  overflow: hidden;
}

._planeHead_f9beb7 {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  border: none;
  background: transparent;
  padding: 10px 12px;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: var(--dsw-alias-label-primary);
}

._planeHead_f9beb7:hover {
  background: var(--dsw-alias-interactive-bg-hover);
}

._avatar_f9beb7 {
  flex: none;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  object-fit: contain;
}

._avatarSm_f9beb7 {
  flex: none;
  width: 20px;
  height: 20px;
  border-radius: 6px;
  object-fit: contain;
}

._planeText_f9beb7 {
  display: flex;
  flex-direction: column;
  gap: 1px;
  flex: 1;
  min-width: 0;
}

._planeName_f9beb7 {
  font-size: 13px;
  font-weight: 600;
  line-height: 20px;
}

._planePurpose_f9beb7 {
  font-size: 11px;
  line-height: 16px;
  color: var(--dsw-alias-label-tertiary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

._count_f9beb7 {
  flex: none;
  font-size: 11px;
  line-height: 16px;
  color: var(--dsw-alias-label-tertiary);
  font-variant-numeric: tabular-nums;
}

._caret_f9beb7 {
  flex: none;
  width: 12px;
  font-size: 10px;
  color: var(--dsw-alias-label-tertiary);
}

/* ── 责任域 ───────────────────────────────────────────── */
._planeBody_f9beb7 {
  display: flex;
  flex-direction: column;
  gap: 2px;
  border-top: 1px solid var(--dsw-alias-border-l1);
  padding: 6px 8px 8px 14px;
}

._domain_f9beb7 {
  display: flex;
  flex-direction: column;
}

._domainHead_f9beb7 {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  border: none;
  background: transparent;
  padding: 6px 8px;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: var(--dsw-alias-label-secondary);
  border-radius: 8px;
}

._domainHead_f9beb7:hover {
  background: var(--dsw-alias-interactive-bg-hover);
  color: var(--dsw-alias-label-primary);
}

._domainName_f9beb7 {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  font-weight: 600;
  line-height: 18px;
}

._domainBody_f9beb7 {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 2px 0 6px 14px;
}

/* ── 岗位 ─────────────────────────────────────────────── */
._role_f9beb7 {
  display: flex;
  flex-direction: column;
}

._roleHead_f9beb7 {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  border: none;
  background: transparent;
  padding: 5px 8px;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: var(--dsw-alias-label-secondary);
  border-radius: 8px;
}

._roleHead_f9beb7:hover {
  background: var(--dsw-alias-interactive-bg-hover);
  color: var(--dsw-alias-label-primary);
}

._roleText_f9beb7 {
  display: flex;
  flex-direction: column;
  gap: 0;
  flex: 1;
  min-width: 0;
}

._roleName_f9beb7 {
  font-size: 12px;
  font-weight: 500;
  line-height: 18px;
  color: var(--dsw-alias-label-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

._roleAgt_f9beb7 {
  font-size: 10px;
  line-height: 14px;
  color: var(--dsw-alias-label-tertiary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

._roleEmpty_f9beb7 {
  flex: none;
  font-size: 10px;
  line-height: 14px;
  padding: 0 6px;
  border-radius: 999px;
  color: var(--dsw-alias-state-warn-primary);
  border: 1px solid var(--dsw-alias-state-warn-primary);
}

._roleBody_f9beb7 {
  padding: 4px 0 8px 26px;
}

/* ── 技能卡 ───────────────────────────────────────────── */
._grid_f9beb7 {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 8px;
}

._card_f9beb7 {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 9px 11px;
  border: 1px solid var(--dsw-alias-border-l1);
  border-radius: 10px;
  background: var(--dsw-alias-bg-layer-2);
  min-width: 0;
}

._cardHead_f9beb7 {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

._cardTitle_f9beb7 {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  font-weight: 500;
  line-height: 17px;
  color: var(--dsw-alias-label-primary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

._cardSummary_f9beb7 {
  margin: 0;
  font-size: 11px;
  line-height: 16px;
  color: var(--dsw-alias-label-secondary);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

._cardFoot_f9beb7 {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
}

._chip_f9beb7 {
  font-size: 10px;
  line-height: 14px;
  padding: 0 6px;
  border-radius: 999px;
  color: var(--dsw-alias-label-tertiary);
  background: var(--dsw-alias-bg-layer-1);
  white-space: nowrap;
}

._chipWired_f9beb7 {
  color: var(--dsw-alias-state-success-primary);
  background: transparent;
  border: 1px solid var(--dsw-alias-state-success-primary);
}

._chipDrift_f9beb7 {
  color: var(--dsw-alias-state-warn-primary);
  background: transparent;
  border: 1px solid var(--dsw-alias-state-warn-primary);
}

._chipOff_f9beb7 {
  color: var(--dsw-alias-label-tertiary);
  border: 1px solid var(--dsw-alias-border-l2);
  background: transparent;
}

/* ── 开关 ─────────────────────────────────────────────── */
._switch_f9beb7 {
  position: relative;
  flex: none;
  width: 34px;
  height: 20px;
  border: none;
  border-radius: 999px;
  cursor: pointer;
  padding: 0;
  background: var(--dsw-alias-border-l2);
  transition: background 0.15s ease;
}

._switchOn_f9beb7 {
  background: var(--dsw-alias-brand-primary);
}

._switch_f9beb7:disabled {
  cursor: default;
  opacity: 0.6;
}

._knob_f9beb7 {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--dsw-alias-bg-overlay);
  transition: left 0.15s ease;
}

._switchOn_f9beb7 ._knob_f9beb7 {
  left: 16px;
}

/* ── 状态行 ───────────────────────────────────────────── */
._hint_f9beb7 {
  font-size: 11px;
  line-height: 16px;
  color: var(--dsw-alias-label-tertiary);
}

._error_f9beb7 {
  font-size: 11px;
  line-height: 16px;
  color: var(--dsw-alias-state-error-primary);
}

._empty_f9beb7 {
  padding: 18px 12px;
  text-align: center;
  font-size: 12px;
  line-height: 18px;
  color: var(--dsw-alias-label-tertiary);
}

._unplaced_f9beb7 {
  border: 1px solid var(--dsw-alias-border-l1);
  border-radius: 12px;
  background: var(--dsw-alias-bg-layer-1);
  overflow: hidden;
}

._unplacedHead_f9beb7 {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  border: none;
  background: transparent;
  padding: 10px 12px;
  cursor: pointer;
  font: inherit;
  text-align: left;
  color: var(--dsw-alias-label-secondary);
}

._unplacedHead_f9beb7:hover {
  background: var(--dsw-alias-interactive-bg-hover);
}

._unplacedName_f9beb7 {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  font-weight: 600;
  line-height: 18px;
}

._unplacedBody_f9beb7 {
  padding: 2px 12px 12px;
  border-top: 1px solid var(--dsw-alias-border-l1);
}

._unplacedNote_f9beb7 {
  margin: 8px 0 10px;
  font-size: 11px;
  line-height: 16px;
  color: var(--dsw-alias-label-tertiary);
}

@media (prefers-reduced-motion: reduce) {
  ._switch_f9beb7,
  ._knob_f9beb7 {
    transition: none;
  }
}
